def _no_duplicate_keys(pairs):
    obj = {}
    for key, value in pairs:
        if key in obj:
            raise Invalid()
        obj[key] = value
    return obj


def _reject_constant(_text):
    raise Invalid()


def _check_float(value):
    if value != value or value in (float('inf'), float('-inf')):
        raise Invalid()
    return value


def parse_request(line):
    if not isinstance(line, (bytes, bytearray)):
        raise Invalid()
    stripped = line.strip()
    if not stripped.startswith(b'{'):
        raise Invalid()
    try:
        obj = json.loads(stripped, object_pairs_hook=_no_duplicate_keys,
                         parse_constant=_reject_constant, parse_float=_check_float)
    except Invalid:
        raise
    except RecursionError:
        raise Invalid()
    except MemoryError:
        raise Invalid()
    except Exception:
        raise Invalid()
    if not isinstance(obj, dict):
        raise Invalid()
    return obj


def parse_fib(raw):
    if not isinstance(raw, list) or len(raw) > MAX_FIB:
        raise Invalid()
    entries = []
    seen = set()
    for rec in raw:
        if not isinstance(rec, dict) or set(rec.keys()) != {'prefix', 'hop'}:
            raise Invalid()
        text = rec['prefix']
        hop = rec['hop']
        if not isinstance(text, str):
            raise Invalid()
        if not is_int(hop) or hop < 0 or hop > MAX_HOP:
            raise Invalid()
        addr, length = parse_prefix(text)
        key = (addr, length)
        if key in seen:
            raise Invalid()
        seen.add(key)
        entries.append((addr, length, hop))
    return entries


def parse_capacities(raw):
    if not isinstance(raw, list) or not (MIN_STAGES <= len(raw) <= MAX_STAGES):
        raise Invalid()
    for cap in raw:
        if not is_int(cap) or cap < 1 or cap > MAX_CAP:
            raise Invalid()
    return list(raw)


def parse_max_stride(raw):
    if not is_int(raw) or raw < 1 or raw > MAX_STRIDE:
        raise Invalid()
    return raw


def do_compile(req):
    if set(req.keys()) != {'op', 'fib', 'capacities', 'max_stride'}:
        raise Invalid()
    entries = parse_fib(req['fib'])
    capacities = parse_capacities(req['capacities'])
    max_stride = parse_max_stride(req['max_stride'])
    table = compute_f([(a, l) for (a, l, h) in entries], max_stride)
    cuts, used, num, den = choose_cuts(table, capacities, max_stride)
    if cuts is None:
        return {'status': 'infeasible'}
    stages = build_stages(entries, cuts)
    return {
        'status': 'ok',
        'capacities': capacities,
        'max_stride': max_stride,
        'cuts': cuts,
        'stages': stages,
        'used_bits': used,
        'peak': {'num': num, 'den': den},
    }


def validate_image(image):
    """Validate a lookup image; returns (fib entries, capacities, cuts)."""
    if not isinstance(image, dict):
        raise Invalid()
    if set(image.keys()) != {'status', 'capacities', 'max_stride', 'cuts',
                             'stages', 'used_bits', 'peak'}:
        raise Invalid()
    if image['status'] != 'ok':
        raise Invalid()
    capacities = parse_capacities(image['capacities'])
    max_stride = parse_max_stride(image['max_stride'])
    stages = len(capacities)
    cuts = image['cuts']
    if not isinstance(cuts, list) or len(cuts) != stages + 1:
        raise Invalid()
    for c in cuts:
        if not is_int(c) or c < 0 or c > 128:
            raise Invalid()
    if cuts[0] != 0 or cuts[stages] != 128:
        raise Invalid()
    for i in range(stages):
        if cuts[i + 1] <= cuts[i] or cuts[i + 1] - cuts[i] > max_stride:
            raise Invalid()
    stage_objs = image['stages']
    if not isinstance(stage_objs, list) or len(stage_objs) != stages:
        raise Invalid()
    fib = []
    seen = set()
    for i, stage in enumerate(stage_objs):
        if not isinstance(stage, dict) or set(stage.keys()) != {'nodes'}:
            raise Invalid()
        nodes = stage['nodes']
        if not isinstance(nodes, list):
            raise Invalid()
        if i == 0 and len(nodes) != 1:
            raise Invalid()
        b = cuts[i]
        e = cuts[i + 1]
        for node in nodes:
            if not isinstance(node, dict) or set(node.keys()) != {'prefix', 'rules', 'edges'}:
                raise Invalid()
            text = node['prefix']
            if not isinstance(text, str):
                raise Invalid()
            addr, length = parse_prefix(text)
            if length != b or text != canonical_prefix(addr, length):
                raise Invalid()
            rules = node['rules']
            if not isinstance(rules, list):
                raise Invalid()
            for rule in rules:
                if not isinstance(rule, dict) or set(rule.keys()) != {'prefix', 'hop'}:
                    raise Invalid()
                rtext = rule['prefix']
                hop = rule['hop']
                if not isinstance(rtext, str):
                    raise Invalid()
                if not is_int(hop) or hop < 0 or hop > MAX_HOP:
                    raise Invalid()
                raddr, rlen = parse_prefix(rtext)
                if rtext != canonical_prefix(raddr, rlen):
                    raise Invalid()
                key = (raddr, rlen)
                if key in seen:
                    raise Invalid()
                seen.add(key)
                fib.append((raddr, rlen, hop))
            edges = node['edges']
            if not isinstance(edges, list):
                raise Invalid()
            for edge in edges:
                if not isinstance(edge, dict) or set(edge.keys()) != {'prefix', 'child'}:
                    raise Invalid()
                etext = edge['prefix']
                child = edge['child']
                if not isinstance(etext, str):
                    raise Invalid()
                if not is_int(child) or child < 0:
                    raise Invalid()
                eaddr, elen = parse_prefix(etext)
                if elen != e or etext != canonical_prefix(eaddr, elen):
                    raise Invalid()
                if i + 1 < stages:
                    if child >= len(stage_objs[i + 1]['nodes']):
                        raise Invalid()
                elif child != 0:
                    raise Invalid()
    if len(fib) > MAX_FIB:
        raise Invalid()
    # the local rules must reproduce exactly the deterministic layout
    table = compute_f([(a, l) for (a, l, h) in fib], max_stride)
    expected = build_stages(fib, cuts)
    for exp_stage, got_stage in zip(expected, stage_objs):
        exp_nodes = exp_stage['nodes']
        got_nodes = got_stage['nodes']
        if len(exp_nodes) != len(got_nodes):
            raise Invalid()
        for exp_node, got_node in zip(exp_nodes, got_nodes):
            if exp_node['prefix'] != got_node['prefix']:
                raise Invalid()
            if len(exp_node['rules']) != len(got_node['rules']):
                raise Invalid()
            for exp_rule, got_rule in zip(exp_node['rules'], got_node['rules']):
                if exp_rule['prefix'] != got_rule['prefix'] or exp_rule['hop'] != got_rule['hop']:
                    raise Invalid()
            if len(exp_node['edges']) != len(got_node['edges']):
                raise Invalid()
            for exp_edge, got_edge in zip(exp_node['edges'], got_node['edges']):
                if exp_edge['prefix'] != got_edge['prefix'] or exp_edge['child'] != got_edge['child']:
                    raise Invalid()
    used = [table[cuts[i]][cuts[i + 1]] for i in range(stages)]
    for i in range(stages):
        if used[i] > capacities[i]:
            raise Invalid()
    given_used = image['used_bits']
    if not isinstance(given_used, list) or len(given_used) != stages:
        raise Invalid()
    for u in given_used:
        if not is_int(u) or u < 0:
            raise Invalid()
    if list(given_used) != used:
        raise Invalid()
    peak = image['peak']
    if not isinstance(peak, dict) or set(peak.keys()) != {'num', 'den'}:
        raise Invalid()
    num = peak['num']
    den = peak['den']
    if not is_int(num) or not is_int(den) or den <= 0 or num < 0:
        raise Invalid()
    if gcd(num, den) != 1:
        raise Invalid()
    best_num = 0
    best_den = 1
    for i in range(stages):
        g = gcd(used[i], capacities[i])
        p = used[i] // g
        q = capacities[i] // g
        if p * best_den > best_num * q:
            best_num = p
            best_den = q
    if num != best_num or den != best_den:
        raise Invalid()
    return fib, capacities, cuts


def do_lookup(req):
    if set(req.keys()) != {'op', 'image', 'addresses'}:
        raise Invalid()
    raw_addresses = req['addresses']
    if not isinstance(raw_addresses, list) or len(raw_addresses) > MAX_ADDRS:
        raise Invalid()
    fib, capacities, cuts = validate_image(req['image'])
    addrs = []
    for text in raw_addresses:
        if not isinstance(text, str):
            raise Invalid()
        addrs.append(parse_ipv6(text))
    by_length = {}
    for addr, length, hop in fib:
        table = by_length.get(length)
        if table is None:
            table = {}
            by_length[length] = table
        table[trunc(addr, length)] = hop
    lengths = sorted(by_length.keys(), reverse=True)
    masks = [(length, ((1 << length) - 1) << (128 - length), by_length[length])
             for length in lengths]
    cache = {}
    answers = []
    for addr in addrs:
        hit = cache.get(addr)
        if hit is None:
            hop = None
            plen = None
            for length, mask, table in masks:
                found = table.get(addr & mask)
                if found is not None:
                    hop = found
                    plen = length
                    break
            hit = (hop, plen)
            cache[addr] = hit
        answers.append({'hop': hit[0], 'prefix_length': hit[1]})
    return {'status': 'ok', 'answers': answers}


def handle(line):
    req = parse_request(line)
    op = req.get('op')
    if op == 'compile':
        return do_compile(req)
    if op == 'lookup':
        return do_lookup(req)
    raise Invalid()


def main():
    debug = bool(os.environ.get('IPV6_PIPELINE_DEBUG'))
    out = sys.stdout
    for raw in sys.stdin.buffer:
        try:
            response = handle(raw)
        except Invalid:
            response = {'status': 'invalid'}
        except Exception:
            if debug:
                raise
            response = {'status': 'invalid'}
        out.write(json.dumps(response, separators=(',', ':')))
        out.write('\n')
        out.flush()


if __name__ == '__main__':
    main()
